public static String testableHtml(
      PageData pageData,
      boolean includeSuiteSetup
      ) throws Exception {
          StringBuffer buffer = generateTestableContent(pageData, includeSuiteSetup);
          pageData.setContent(buffer.toString());
          return pageData.getHTML();
      }

private static StringBuffer generateTestableContent(PageData pageData, boolean includeSuiteSetup) {
    StringBuffer buffer = new StringBuffer();
    if (pageData.hasAttribute("Test")) {
        generateSetupInclusions(pageData, includeSuiteSetup, buffer);
        buffer.append(pageData.getContent());
        generateTeardownInclusions(pageData, includeSuiteSetup, buffer);
    }
    return buffer;
}

private static void generateSetupInclusions(PageData pageData, boolean includeSuiteSetup, StringBuffer buffer) {
    WikiPage wikiPage = pageData.getWikiPage();
    if (includeSuiteSetup) {
        addInheritedPage(buffer, SuiteResponder.SUITE_SETUP_NAME, "!include -setup .", wikiPage);
    }
    addInheritedPage(buffer, "SetUp", "!include -setup .", wikiPage);
}

private static void generateTeardownInclusions(PageData pageData, boolean includeSuiteSetup, StringBuffer buffer) {
    WikiPage wikiPage = pageData.getWikiPage();
    addInheritedPage(buffer, "TearDown", "!include -teardown .", wikiPage);
    if (includeSuiteSetup) {
        addInheritedPage(buffer, SuiteResponder.SUITE_TEARDOWN_NAME, "!include -teardown .", wikiPage);
    }
}

private static void addInheritedPage(StringBuffer buffer, String pageName, String prefix, WikiPage wikiPage) {
    WikiPage page = PageCrawlerImpl.getInheritedPage(pageName, wikiPage);
    if (page != null) {
        WikiPagePath pagePath = page.getPageCrawler().getFullPath(page);
        String pagePathName = PathParser.render(pagePath);
        buffer.append(prefix).append(pagePathName).append("\n");
    }
}
